(() => {
  const selectors = %s;
  const heuristicFallback = %s;
  // 크롬(내비/헤더/푸터) 배제 — body 를 잡으면 메뉴 텍스트가 콘텐츠로 섞여 분모를 부풀린다.
  const CHROME = 'header,nav,footer,aside,[role=banner],[role=navigation],[role=contentinfo]';
  const out = [];
  const roots = [];
  for (const sel of selectors) document.querySelectorAll(sel).forEach(n => roots.push(n));
  const seen = new Set();
  // 이미지 URL 은 **lazy 원본 속성 최우선** — src 를 승격해도 currentSrc 는 로드 시작 전까지
  // loading.gif 를 유지해 플레이스홀더가 캡처된다(2026-07-14 실측). 속성이 곧 진실이다.
  const LZ = ['data-flixsrcset', 'data-srcset', 'data-src', 'data-lazy-src'];
  const ab = u => (u || '').startsWith('//') ? 'https:' + u : u;
  const f1 = v => (v || '').split(',')[0].trim().split(' ')[0];
  const iurl = (img) => {
    for (const a of LZ) { const d = img.getAttribute(a); if (d) return ab(f1(d)); }
    return img.currentSrc || img.src || '';
  };
  // 캡처 본체 — 셀렉터 경로와 휴리스틱 폴백이 같은 로직을 쓰므로 한 함수로 공유한다
  // (중복 코드를 두면 SB 요청 길이 한도 8,190자를 넘겨 400 이 난다).
  const grab = (root, minImg) => {
    root.querySelectorAll('img').forEach(img => {
      if (seen.has(img) || img.closest(CHROME)) return;
      seen.add(img);
      const r = img.getBoundingClientRect();
      if (r.width < minImg || r.height < minImg) return;
      out.push({kind:'image', box:[r.x, r.y, r.width, r.height], url: iurl(img)});
    });
    root.querySelectorAll('*').forEach(el => {
      if (seen.has(el) || el.closest(CHROME)) return;
      seen.add(el);
      const text = Array.from(el.childNodes).filter(n => n.nodeType === 3)
        .map(n => n.textContent).join(' ').trim();
      if (!text || text.length > 200) return;
      const r = el.getBoundingClientRect();
      if (r.width < 2 || r.height < 2) return;
      const cs = getComputedStyle(el);
      out.push({kind:'text', box:[r.x, r.y, r.width, r.height], text,
                font_size: parseFloat(cs.fontSize) || 0, align: cs.textAlign, color: cs.color,
                border_width: cs.borderTopWidth, border_style: cs.borderTopStyle});
    });
  };
  for (const root of roots) grab(root, 2);
  // ⚠️ **컨테이너가 있으면 절대 폴백하지 않는다**(2026-07-14 ECI 실증): flix 컨테이너가 있는데
  // 콘텐츠 주입 전이면 페이지 전체를 긁어 갤러리·UI 를 공식 콘텐츠와 대조하게 된다.
  // 폴백은 컨테이너 자체가 없는 리테일러(Media Markt 등 해시 클래스 자체 CDN)에만 허용한다.
  if (heuristicFallback && roots.length === 0) grab(document.body, 40);

  const blob = roots.length
    ? roots.map(r => r.innerText || '').join('
')
    : (document.body.innerText || '');

  // 비디오 재생 판정 — SB 는 실브라우저라 <video> 의 error/readyState 를 그대로 읽는다.
  const vids = [];
  document.querySelectorAll('video').forEach(v => {
    const s0 = v.querySelector('source');
    const src = v.currentSrc || v.src || (s0 ? (s0.src || s0.getAttribute('src') || '') : '');
    vids.push({kind: 'video', src: src, error: v.error ? v.error.code : null,
               readyState: v.readyState, networkState: v.networkState});
  });
  document.querySelectorAll('iframe').forEach(f => {
    const s = f.src || '';
    if (/youtube|youtu\.be|vimeo|flixcar|brightcove|cliplister|player/i.test(s))
      vids.push({kind: 'embed', src: s});
  });
  // 클릭형 팝업 비디오 — 플레이어는 클릭 후에만 뜨고 DOM 엔 비디오 서비스 썸네일만 있다
  // (MediaMarkt Cliplister 실측: 썸네일 4·refs 17 인데 video/iframe 0 → "영상 있는데 0").
  document.querySelectorAll('img').forEach(im => {
    const u = im.currentSrc || im.src || '';
    if (/cliplister|img\.youtube\.com\/vi\/|i\.ytimg\.com|vimeocdn/i.test(u))
      vids.push({kind: 'popup', src: u});
  });

  // 렌더 결함(ID43) — **에셋 컨테이너 안에서만**(로컬 acapture_render_defects 와 동일 계약).
  // body 전체를 훑으면 "No has seleccionado una tienda"(매장 선택기) 같은 UI 크롬이 결함으로
  // 잡힌다(2026-07-14 실측: 잘림 165건이 전부 그런 것이었다). roots 가 없으면 판정하지 않는다.
  const rd = roots.length ? {truncated: [], broken_images: []} : null;
  const seenT = new Set(), seenI = new Set();
  for (const root of roots) {
    root.querySelectorAll('*').forEach(el => {
      if (el.closest(CHROME)) return;
      const cs = getComputedStyle(el);
      if (cs.textOverflow === 'ellipsis' && el.scrollWidth > el.clientWidth + 1) {
        const t = (el.innerText || '').trim().slice(0, 80);
        if (t && !seenT.has(t)) { seenT.add(t); rd.truncated.push(t); }
      }
    });
    root.querySelectorAll('img').forEach(img => {
      if (img.closest(CHROME)) return;
      if (img.complete && img.naturalWidth === 0) {
        // UI 아이콘·0×0(CSS 미적용) 배제(MIN_CONTENT_IMG_PX=200, 2026-07-31 — 0도 포함해야
        // CSS 클래스 의존 요소가 스타일시트 없이 0×0 렌더되는 경우를 잡는다)
        const r = img.getBoundingClientRect();
        if (Math.max(r.width, r.height) < 200) return;
        const u = img.currentSrc || img.src || '';
        if (u && !seenI.has(u)) { seenI.add(u); rd.broken_images.push(u); }
      }
    });
  }

  const s = document.createElement('script');
  s.id = '__official_blocks__'; s.type = 'application/json';
  s.textContent = JSON.stringify(out); document.body.appendChild(s);
  const m = document.createElement('script');
  m.id = '__capture_meta__'; m.type = 'application/json';
  m.textContent = JSON.stringify({roots: roots.length, fallback: roots.length === 0 && heuristicFallback,
                                  flixDiv: !!document.querySelector('#flix-inpage,#flix-minisite'),
                                  text: blob.slice(0, 30000), videos: vids, render_defects: rd});
  document.body.appendChild(m);
})()

(() => {
  const LAZY = ['data-flixsrcset', 'data-srcset', 'data-src', 'data-lazy-src'];
  const abs = u => (u || '').startsWith('//') ? 'https:' + u : u;
  const firstUrl = v => (v || '').split(',')[0].trim().split(' ')[0];
  // ⚠️ **이미지도 lazy 다.** FlixMedia 는 <img src="…/images/loading.gif"> 로 두고 실제 URL 을
  // data-flixsrcset 에 넣는다(2026-07-14 실측: ECI 콘텐츠 이미지 406장 중 323장(80%)·Unieuro
  // 65%가 loading.gif). 승격하지 않으면 이미지 개수가 부풀고 dHash 는 loading.gif 끼리 비교돼
  // 전부 미매칭이 된다 — ID43 이미지 축이 통째로 왜곡된다.
  document.querySelectorAll('img').forEach(im => {
    try {
      for (const a of LAZY) {
        const d = im.getAttribute(a);
        if (d && (!im.src || im.src.includes('loading') || im.src.startsWith('data:'))) {
          im.src = abs(firstUrl(d));
          im.removeAttribute('srcset');
          break;
        }
      }
    } catch (e) {}
  });
  document.querySelectorAll('video').forEach(v => {
    try {
      for (const a of LAZY) {
        const d = v.getAttribute(a);
        if (!v.src && d) { v.src = abs(firstUrl(d)); break; }
      }
      v.querySelectorAll('source').forEach(s => {
        for (const a of LAZY) {
          const d = s.getAttribute(a);
          if (!s.getAttribute('src') && d) { s.setAttribute('src', abs(firstUrl(d))); break; }
        }
      });
      v.muted = true;                 // muted 여야 자동재생 정책을 통과한다
      v.playsInline = true;
      v.load();
      const p = v.play();
      if (p && p.catch) p.catch(() => {});
    } catch (e) {}
  });
  const sels = ['button[aria-label*=play i]', 'button[class*=play i]', '[class*=play-button]',
                '[data-testid*=play]', '.video-play', 'button[title*=play i]'];
  for (const s of sels) {
    document.querySelectorAll(s).forEach(b => { try { b.click(); } catch (e) {} });
  }
})()
